String? resolveBundledAsset(String? query) {
  if (query == null || query.isEmpty) return null;
  var str = query.trim();
  if (str.startsWith('assets/')) {
    str = str.split('/').last;
  } else if (str.startsWith('http')) {
    final uri = Uri.tryParse(str);
    str = (uri != null && uri.pathSegments.isNotEmpty)
        ? uri.pathSegments.last
        : str.split('/').last;
    str = Uri.decodeComponent(str);
  }
  // Strip file extension if present
  final dot = str.lastIndexOf('.');
  if (dot > 0) {
    str = str.substring(0, dot);
  }
  // Strip volume/unit brackets like (80 ml)
  str = str.replaceFirst(RegExp(r'\s*\([^)]*\)\s*$'), '');
  final clean = str
      .toLowerCase()
      .replaceAll(RegExp(r'[^a-z0-9]+'), '-')
      .replaceAll(RegExp(r'^-+|-+$'), '');
  if (clean.isEmpty) return null;
  return productAssetRegistry[clean];
}
